/**
 * The app's core. The Swift app opens one per process and shares it.
 */
public protocol RelayCoreProtocol: AnyObject, Sendable {
    
    /**
     * The host's background time ran out: finishing work stops.
     */
    func backgroundTimeExpired() 
    
    /**
     * Whether commands or finishing work are still running; the
     * host holds background time while they are.
     */
    func backgroundWorkPending()  -> Bool
    
    /**
     * Stops the receive in progress, if any; it ends with an error, and
     * what arrived stays for a resume.
     */
    func cancelCodeReceive() 
    
    /**
     * Stops the code send in progress, if any; it ends as `Failed`.
     */
    func cancelCodeSend() 
    
    /**
     * Withdraws the open pairing code.
     */
    func cancelInvitation() 
    
    /**
     * The size of the file being received with a code, and how much of it
     * was already here from an earlier try; `None` when none is running or
     * the sender hasn't named the file yet.
     */
    func codeReceiveSize()  -> CodeSize?
    
    /**
     * The code send in progress or last finished; `None` before the first.
     */
    func codeSendStatus()  -> CodeSendStatus?
    
    /**
     * A pairing code for the other device to scan, valid once for five
     * minutes. `hosts` are this device's addresses on the local network
     * (the app reads them from `NWPathMonitor`); the listening port is
     * added. Start listening first.
     */
    func createInvitation(hosts: [String]) throws  -> Invitation
    
    /**
     * The runtime's event stream: `Changed { revision }` after each
     * committed command, phase changes, and drops. Nil after shutdown.
     */
    func events()  -> RuntimeEvents?
    
    /**
     * Unpairs a device: its secret is deleted, so it can't connect again
     * until it pairs again. Its history stays.
     */
    func forgetPeer(deviceId: String) async throws 
    
    /**
     * This device, as others see it.
     */
    func identity()  -> Identity
    
    /**
     * What the runtime found at open (unfinished background work).
     */
    func launchReport()  -> LaunchReport
    
    /**
     * The port Relay listens on, if it does.
     */
    func listeningPort()  -> UInt16?
    
    /**
     * Pairs with the device whose code was scanned: connects to it, proves
     * both hold the code's secret, and keeps the other device. Expires
     * with the code (the other device refuses it).
     */
    func pair(code: String, cancellation: Cancellation?) async throws  -> Peer
    
    /**
     * Paired devices, by name.
     */
    func peers()  -> [Peer]
    
    /**
     * The phase last reported.
     */
    func phase()  -> AppPhase
    
    /**
     * Receives the file a sender offers with a word code such as
     * `37-grasp-gag-drum` (Relay M1; the sender is `relay-spike send` on a
     * computer for now). `addresses` and `endpoint_id` come from the
     * sender's Bonjour advertisement (`CODE_SERVICE_TYPE`, TXT `n` = the
     * code's number, `id` = the endpoint id). The file is verified chunk by
     * chunk and saved in Relay's `codes/received` folder; a dropped receive
     * resumes with the sender's next code. One at a time.
     */
    func receiveWithCode(code: String, addresses: [String], endpointId: String) async throws  -> CodeReceipt
    
    /**
     * Removes a history entry and, for a received file, the file.
     */
    func removeTransfer(id: UInt64) async throws 
    
    func renameDevice(name: String) async throws 
    
    /**
     * The last committed revision.
     */
    func revision()  -> UInt64
    
    /**
     * Sends the file at `path` to a paired device. The file must stay put
     * until the transfer ends.
     */
    func sendFile(deviceId: String, path: String, addresses: [String], cancellation: Cancellation?) async throws  -> Transfer
    
    /**
     * Sends a note to a paired device at `addresses` ("host:port", from
     * Bonjour), or where it was last reached when there are none.
     */
    func sendNote(deviceId: String, text: String, addresses: [String], cancellation: Cancellation?) async throws  -> Transfer
    
    /**
     * Sends the file at `path` with a word code: this device waits for a
     * receiver on the local network (Relay M1). Returns the first code and
     * what the app advertises with Bonjour (`CODE_SERVICE_TYPE` on `port`,
     * TXT `v=1`, `n` = the code's number, `id` = `endpoint_id`). The send
