         */note: String, name: String, size: UInt64, 
        /**
         * From the receiver proving the code to it saying it has the file.
         */seconds: Double, megabytesPerSecond: Double) {
        self.state = state
        self.code = code
        self.number = number
        self.generation = generation
        self.note = note
        self.name = name
        self.size = size
