/**
 * Everything that can go wrong, in the app's words. `relay_error_kind`
 * maps each case to the framework's [`ErrorKind`].
 */
public 
enum RelayError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case EmptyName
    case NameTooLong(max: UInt32
    )
    case EmptyNote
    case NoteTooLong(max: UInt32
    )
    case FileTooLarge
    case BadCode
    case CodeExpired
    /**
     * A transfer code (`7-acid-tidy-rug`) that can't be right as typed.
     */
    case WordCode(reason: String
    )
    case UnknownPeer(id: String
    )
    case NotFound(id: UInt64
    )
    case Unreachable(reason: String
    )
    case Refused
    case Declined(reason: String
    )
    case Connection(reason: String
    )
    case File(reason: String
    )
    case AlreadyListening
    case InUse
    case Corrupt(reason: String
    )
    case NewerData
    case Storage(reason: String
    )
    /**
     * Stopped by the runtime: cancelled, interrupted by the background,
     * or shut down. `kind` says which.
     */
    case Stopped(kind: ErrorKind
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

